// Home Health Aide Practice Test 6. Original questions written for Valus from the HOSA 2026–27 test plan,
// slightly harder than the sample items and covering topics not used in Practice Tests 1–5.
import {q, mix} from './q.js';
const BAL='Balduzzi, Homemaker Home Health Aide', HART='Leahy, Fuzy & Grafe, Providing Home Care';
const RESP='Responsibilities and Legal/Ethical Issues', COMM='Effective Communication', INF='Infection Control and Safety', BODY='Body Systems and Common Disorders', SPEC='Caring for Special Populations', SKILL='Basic Healthcare Skills';

export default {
 id:'home-health-aide-6',
 event:'Home Health Aide',
 title:'Practice Test 6',
 subtitle:'Full-length Round One simulation',
 minutes:60,
 sources:'Balduzzi’s Homemaker Home Health Aide and Leahy, Fuzy & Grafe’s Providing Home Care',
 plan:[{area:RESP,weight:10},{area:COMM,weight:6},{area:INF,weight:10},{area:BODY,weight:40},{area:SPEC,weight:24},{area:SKILL,weight:10}],
 questions:mix([
  q(RESP,'An aide wants to move a client’s kitchen items to make cleaning easier. What should the aide do first?','Ask the client, because it is the client’s home',['Rearrange everything and explain later','Ask the neighbor for permission','Throw away items that seem unneeded'],'A','Respecting the client’s home and choices supports dignity and trust.',BAL),
  q(RESP,'Which household task is usually part of a home health aide’s duties?','Light housekeeping in the client’s living areas',['Repairing the roof and gutters','Painting the outside of the house','Mowing the lawn of the whole street'],'B','Aides keep the client’s area clean and safe; major repairs are not part of the role.',BAL),
  q(RESP,'An aide leaves a client who needs constant supervision before the next caregiver arrives. What is this?','Abandonment',['Delegation','Documentation','Advocacy'],'C','Leaving a dependent client without proper handoff can cause harm and is a legal issue.',HART),
  q(RESP,'How many hours of in-service training must home health aides complete each year under federal rules?','At least 12 hours',['At least 1 hour','At least 4 hours','At least 75 hours'],'D','Annual in-service training keeps skills up to date and is required for Medicare-certified agencies.',HART),
  q(RESP,'Before entering a client’s bedroom when the door is closed, what should the aide do?','Knock and wait for permission',['Walk in quietly so as not to disturb','Call the supervisor first','Open the door and announce care loudly'],'A','Knocking and waiting protects privacy and shows respect for the client’s personal space.',BAL),
  q(COMM,'A client sits with arms crossed and avoids looking at the aide. What might this body language suggest?','The client may be uncomfortable, upset or closed off',['The client is definitely happy and relaxed','The client wants to go for a walk','The client is about to fall asleep'],'B','Nonverbal cues should be gently explored, such as asking how the client is feeling.',BAL),
  q(COMM,'A client says, “I didn’t take it today.” The aide asks, “Do you mean your blood pressure pill?” Which skill is this?','Clarifying',['Giving advice','Changing the subject','Making a judgment'],'C','Clarifying makes sure the aide understands the client’s meaning before reporting it to the nurse.',BAL),
  q(COMM,'A client visits with a friend who answers every question for her. How should the aide communicate?','Speak directly to the client, not to the friend',['Speak only to the friend, since the friend seems to know the client well','Ignore the client and write notes','Ask the friend to leave right away'],'D','Speaking to the client respects their dignity and right to make decisions.',BAL),
  q(INF,'An aide arrives at a client’s home and finds an angry, intoxicated visitor making threats. What should the aide do?','Leave if unsafe and call the agency and, if needed, 911',['Stay and calmly argue with the visitor until they agree to leave the client’s home','Lock the visitor in a room','Ignore the threats and start care'],'A','Aide safety comes first; report unsafe situations right away.',BAL),
  q(INF,'How should a used dressing soaked with blood be disposed of in the home?','Place it in a plastic bag, seal it and double-bag before putting it in the trash',['Flush it down the toilet in small pieces so it does not clog the pipes or drain','Leave it on the floor for the family','Put it in the recycling bin'],'B','Double-bagging contains body fluids and protects family members and trash handlers.',BAL),
  q(INF,'How far should a space heater be kept from beds, curtains and furniture?','At least 3 feet',['At least 3 inches','About 6 inches','It can touch furniture safely'],'C','Space heaters are a common cause of home fires and should be turned off when no one is in the room.',BAL),
  q(INF,'Which emergency information should be posted near the client’s phone?','Emergency numbers, the client’s address and medical contacts',['The client’s bank account number and online banking passwords for bills','The aide’s home address','The client’s passwords'],'D','In an emergency, quick access to numbers and the address saves time.',BAL),
  q(INF,'When may alcohol-based hand sanitizer be used instead of soap and water?','When hands are not visibly soiled',['When hands have visible blood on them','After caring for a client with C. diff diarrhea','After using the restroom with dirty hands'],'A','Soap and water are needed for visible dirt and certain germs, such as C. diff.',BAL),
  q(BODY,'A client has a cough, fever, chills and trouble breathing. Which lung infection is most likely?','Pneumonia',['Asthma','Emphysema','Lung cancer'],'B','Pneumonia is especially dangerous for older adults and should be reported promptly.',HART),
  q(BODY,'A client had a brief episode of slurred speech and arm weakness that went away in 10 minutes. Why must it be reported?','It may be a TIA, a warning sign of a future stroke',['It means the client needs more sleep and should rest for the remainder of the day','It is a normal part of aging','It is a sign of a cold'],'C','A transient ischemic attack needs prompt medical evaluation to prevent a stroke.',HART),
  q(BODY,'A client has a throbbing headache with nausea and sensitivity to light. Which comfort measure may help?','A dark, quiet room with a cool cloth',['Bright lights and loud music','Exercise in hot sun','A large heavy meal'],'D','Migraines often improve with rest in a dark, quiet place; report new or unusually severe headaches.',HART),
  q(BODY,'Which inherited disease causes jerky, uncontrolled movements and gradual changes in thinking and mood?','Huntington disease',['Parkinson disease','Cerebral palsy','Myasthenia gravis'],'A','Huntington disease usually begins in midlife and worsens over time.',HART),
  q(BODY,'A client with hepatitis has yellow skin and eyes. Which organ is affected?','The liver',['The lungs','The kidneys','The bladder'],'B','Hepatitis is liver inflammation; hepatitis B and C spread through blood.',HART),
  q(BODY,'A client has pain in the upper right abdomen after fatty meals. What may cause this?','Gallstones',['Kidney stones','Asthma','Cataracts'],'C','Gallstones can block bile flow; low-fat meals may reduce attacks.',HART),
  q(BODY,'A client on dialysis has a fistula in the left arm. What should the aide avoid?','Taking blood pressure or putting tight items on that arm',['Feeling gently for a buzz (thrill) over the fistula each day','Keeping the arm clean','Reporting bleeding from the site'],'D','Pressure on the access arm can damage the fistula, which is the client’s lifeline for dialysis.',HART),
  q(BODY,'A client says sounds seem muffled in one ear, and earwax is visible. What should the aide do?','Report it, and never insert cotton swabs or objects into the ear',['Remove the wax gently with a clean hairpin or the end of a cotton swab','Pour hot water into the ear','Push the wax deeper with a cotton swab'],'A','Impacted earwax is removed by a nurse or provider; objects can damage the eardrum.',HART),
  q(BODY,'A client has been on bed rest for weeks and the muscles have become smaller and weaker. What is this called?','Muscle atrophy',['Muscle hypertrophy','Muscle spasm','Muscle strain'],'B','Activity, range-of-motion and exercise as ordered help prevent atrophy in clients on bed rest.',HART),
  q(BODY,'A client has intense itching, worse at night, with a rash between the fingers. Which condition should be suspected?','Scabies',['Shingles','Psoriasis','Acne'],'C','Scabies mites spread by close contact; report it so treatment can start.',HART),
  q(BODY,'A client feels dizzy when standing up quickly from bed. What is this called?','Orthostatic hypotension',['Hypertension (high blood pressure)','Hyperglycemia (high blood sugar)','Hypothermia (low body temperature)'],'D','Have the client sit on the edge of the bed and dangle the legs for a moment before standing.',HART),
  q(BODY,'Why are older adults at higher risk of hypothermia at home?','They may sense cold less and produce less body heat',['They always keep the heat too high','They have more body fat than younger adults','They sweat more in cold weather'],'A','Keep the home warm and watch for confusion, shivering and cold skin.',HART),
  q(BODY,'A client with trouble swallowing coughs during meals and later has a fever. What may have happened?','Aspiration pneumonia from food or liquid entering the lungs',['A heart attack caused by a blocked artery','A kidney stone blocking the ureter','A migraine triggered by bright light'],'B','Upright positioning and the ordered diet texture reduce aspiration risk.',HART),
  q(BODY,'While bathing a client, the aide feels a new lump in the client’s breast. What should the aide do?','Report it to the supervisor',['Ignore it because it is probably nothing','Massage the lump firmly','Tell the client it is cancer'],'C','Aides observe and report changes; diagnosis is the provider’s role.',HART),
  q(BODY,'A client leaks a small amount of urine when coughing or sneezing. Which type of incontinence is this?','Stress incontinence',['Overflow incontinence','Functional incontinence','Urge incontinence'],'D','Stress incontinence is common after childbirth and in older women; pelvic floor exercises can help.',HART),
  q(BODY,'An aide counts a client’s pulse and notices it is irregular. What should the aide do?','Count for a full minute and report it',['Count for 10 seconds and multiply by 6','Ignore it because irregular pulses are normal','Have the client run in place'],'A','An irregular pulse may signal a heart rhythm problem that needs follow-up.',HART),
  q(BODY,'Which heart attack symptoms may be more common in women?','Unusual fatigue, nausea and pain in the back or jaw',['Only sudden crushing pain in the center of the chest','A raised, itchy rash on the lower legs','Increased appetite and thirst over weeks'],'B','Women may not have classic chest pain; report any of these symptoms right away.',HART),
  q(BODY,'A client with anemia is advised to eat iron-rich foods. Which choice is best?','Lean red meat, beans and leafy greens',['White bread and butter','Candy, cookies and regular soda','Tea and crackers between meals'],'C','Eating vitamin C foods, such as oranges, with iron-rich foods improves iron absorption.',HART),
  q(BODY,'Why is high blood pressure often called a “silent killer”?','It usually causes no symptoms while it damages the heart, brain and kidneys',['It makes people suddenly unable to speak or call for help during a blood pressure attack','It only happens during sleep, when no one notices','It always causes loud ringing in the ears'],'A','Regular blood pressure checks find hypertension early, before it leads to stroke, heart attack or kidney failure.',HART),
  q(SPEC,'How should an aide guide a client who is blind while walking?','Let the client hold the aide’s arm just above the elbow and walk slightly ahead',['Push the client gently from behind by the shoulders while giving directions out loud','Pull the client forward by the wrist quickly','Walk several steps behind and call out directions'],'B','The client can feel the aide’s movements, such as turns and steps, and the aide should describe obstacles.',BAL),
  q(BODY,'A client hit their head in a fall and is now confused and vomiting. What should the aide do?','Call 911 and notify the supervisor',['Let the client sleep it off','Give the client pain medicine','Wait until the next visit'],'D','Confusion and vomiting after a head injury may signal bleeding in the brain.',HART),
  q(SPEC,'How should a baby’s diaper rash be cared for?','Change diapers often and keep the skin clean and dry',['Leave wet diapers on longer','Use scented baby wipes and powder heavily','Wash the area with hot water'],'A','Frequent changes and protective ointment as directed help the skin heal.',BAL),
  q(SPEC,'A baby will not stop crying, and the aide feels frustrated. What is the safest action?','Place the baby safely in the crib and take a short break',['Shake the baby gently up and down for a few seconds to calm them down','Leave the home immediately','Yell at the baby to stop crying'],'B','Shaking a baby can cause brain injury or death; it is never safe.',BAL),
  q(SPEC,'A toddler throws a tantrum at bath time. How should the aide respond?','Stay calm and offer simple choices',['Spank the child','Yell until the child stops','Give candy every time the child cries'],'C','Offering choices, such as which toy to bring, gives toddlers a sense of control.',BAL),
  q(SPEC,'A client with schizophrenia says he hears voices telling him he is in danger. How should the aide respond?','Stay calm, do not argue about the voices and report it',['Tell him the voices are real and help him search the house for the danger they describe','Laugh to lighten the mood','Leave him alone for the rest of the day'],'D','Acknowledge his fear without agreeing that the voices are real.',BAL),
  q(SPEC,'A client with bipolar disorder is talking rapidly and has not slept. Which environment may help?','A calm, quiet space with few distractions',['A loud room with many visitors','A room with bright flashing lights','A busy store'],'A','Overstimulation can worsen mania; report symptoms to the supervisor.',BAL),
  q(SPEC,'An aide finds many empty pill bottles and smells alcohol on a client who seems drowsy. What should the aide do?','Report the observations to the supervisor right away',['Ignore it to respect the client’s privacy and right to make choices at home','Pour out the client’s alcohol','Leave the client alone'],'B','Possible substance misuse or overdose needs prompt reporting and, if severe, emergency help.',BAL),
  q(SPEC,'A veteran with PTSD startles and becomes upset when the aide enters quietly from behind. How can the aide help?','Announce themself and approach from the front',['Sneak in so the client does not wake','Tap the client’s shoulder suddenly','Turn off all the lights'],'C','Predictable, calm approaches from the front reduce trauma triggers for clients with PTSD.',BAL),
  q(SPEC,'A client’s home is filled with piles of items blocking exits and walkways. Why is this a concern?','It creates fall and fire hazards and should be reported',['It shows the client is very organized and has planned ahead for emergencies','It means the client needs more items','It is never a safety concern'],'D','Hoarding can trap residents during fires and cause falls; the agency can arrange help.',BAL),
  q(SPEC,'A family is grieving after a client dies at home. What is the aide’s role?','Offer quiet support and follow the agency’s procedures',['Leave immediately without speaking','Tell the family to stop crying','Share stories about other clients who died'],'A','Respecting family wishes and cultural practices is important after a death.',BAL),
  q(SPEC,'A client who is hard of hearing reads lips. How should the aide position themself?','Face the client in good light',['Stand behind the client','Stand in a dark corner','Cover the mouth while speaking'],'B','Lip reading needs a clear view of the speaker’s face, so avoid backlighting and covering the mouth.',BAL),
  q(SPEC,'A client weighs 400 pounds. What should the aide check before using a lift or shower chair?','The equipment’s weight limit',['The equipment’s color','The equipment’s brand only','Nothing, all equipment holds any weight'],'C','Bariatric equipment is designed for higher weights and prevents injury.',BAL),
  q(SKILL,'When taking a tympanic temperature on an adult, how should the ear be pulled?','Up and back',['Down and forward','Straight down','Straight forward'],'D','Pulling up and back straightens the adult ear canal for an accurate reading.',BAL),
  q(SKILL,'When giving perineal care to a female client, in what direction should the aide wipe?','From front to back',['From back to front','In circles over the whole area','In any direction'],'A','Wiping front to back keeps rectal bacteria away from the urethra.',BAL),
  q(SKILL,'Where should the aide sit when feeding a client?','At eye level with the client',['Standing over the client','Behind the client','Across the room'],'B','Sitting at eye level is respectful and helps the aide watch for swallowing problems.',BAL),
  q(SKILL,'How should tangled hair be combed?','Start at the ends and work up toward the scalp',['Start at the scalp and pull firmly through to the ends in one stroke','Cut out the tangles','Comb only when wet with hot water'],'C','Working from the ends toward the scalp prevents pulling, pain and hair breakage.',BAL),
  q(SKILL,'Before trimming a client’s fingernails (if allowed), what helps soften them?','Soaking the hands in warm water',['Freezing the hands','Rubbing alcohol on the nails','Soaking in bleach'],'D','Softened nails are easier to trim safely; nails of clients with diabetes are trimmed only by a nurse or podiatrist.',BAL)
 ],9613)
};
